     7	const ajv = new Ajv({strict: false, validateFormats: false});
     8	
     9	export interface ToolResponse {
    10	  result: string;
    11	  clientMessages?: OutgoingMessage[];
    12	  suppressAssistantResponse?: boolean;
    13	}
    14	
    15	export interface ToolContext {
    16	  userId: string | number;
    17	  sessionId?: string;
    18	  workspaceId?: string | number;
    19	  authHeaders?: {
    20	    cookie?: string;
    21	    authorization?: string;
    22	    host?: string;
    23	  };
    24	}
    25	
    26	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
    27	
    28	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
    29	  return typeof response === 'string' ? {result: response} : response;
    30	}
    31	
    32	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
    33	
    34	// Names the path and constraint only; ajv's message never includes the offending value.
    35	function describeError(error: ErrorObject): string {
    36	  if (error.keyword === 'required') return `${String(error.params.missingProperty)} is required`;
    37	  return `${error.instancePath || 'input'} ${error.message ?? 'is invalid'}`;
    38	}
    39	
    40	export interface RegisteredTool {
    41	  definition: ToolDefinition;
    42	  execute: ToolExecutor;
    43	}
    44	
    45	interface StoredTool {
    46	  definitionSource: ToolDefinitionSource;
    47	  execute: ToolExecutor;
    48	  validate?: ValidateFunction;
    49	}
    50	
    51	export class ToolRegistry {
    52	  private readonly tools = new Map<string, StoredTool>();
    53	
    54	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    55	    return typeof source === 'function' ? source() : source;
    56	  }
    57	
    58	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    59	    const resolved = this.resolveDefinition(definition);
    60	    const validate = typeof definition === 'function' ? undefined : this.compile(resolved);
    61	    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
    62	  }
    63	
    64	  private compile(definition: ToolDefinition): ValidateFunction {
    65	    try {
    66	      return ajv.compile(definition.inputSchema);
    67	    } catch (error) {
    68	      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${(error as Error).message}`, {cause: error});
    69	    }
    70	  }
    71	
    72	  get(name: string): RegisteredTool | undefined {
    73	    const tool = this.tools.get(name);
    74	    if (!tool) return undefined;
    75	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
    76	  }
    77	
    78	  getDefinitions(): ToolDefinition[] {
    79	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
    80	  }
    81	
    82	  getPromptInstructions(): string[] {
    83	    return this.getDefinitions()
    84	      .filter(t => t.promptInstructions)
    85	      .map(t => `${t.name}: ${t.promptInstructions}`);
    86	  }
    87	
    88	  getExamplePrompts(): string[] {
    89	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
    90	  }
    91	
    92	  has(name: string): boolean {
    93	    return this.tools.has(name);
    94	  }
    95	
    96	  /** Returns a rejection ToolResponse for schema-invalid input; see specs/hal-engine-tool-input-validation/spec.md. */
    97	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    98	    const tool = this.tools.get(name);
    99	    if (!tool) {
   100	      log.warn('tool', 'tool not found', {name});
   101	      throw new Error(`Unknown tool: ${name}`);
   102	    }
   103	    if (tool.validate && !tool.validate(input)) {
   104	      const errors = (tool.validate.errors ?? []).map(describeError);
   105	      log.warn('tool', 'input rejected', {name, errors});
   106	      return {result: `Invalid input for tool ${name}: ${errors.join('; ')}`};
   107	    }
   108	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
   109	    const rawResult = await tool.execute(input, context);
   110	    const response = normalizeToolResponse(rawResult);
   111	    log.info('tool', 'execution complete', {
   112	      name,
   113	      rawType: typeof rawResult,
   114	      clientMessageCount: response.clientMessages?.length ?? 0,
   115	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
   116	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
   117	    });
   118	    return response;
   119	  }
   120	}
